package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheets: a row per id ever loaded. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Create the sheet if its id was never used (its today the real date); an existing sheet is left as it is. */
    public void ensure(String id) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, COALESCE((SELECT today FROM sheet WHERE id = ?), ?)",
                id, id, LocalDate.now());
    }

    /**
     * The sheet's today. Every decision that depends on the date, and every default date, uses
     * this — never the real clock. A sheet not yet stored is on the real date.
     */
    public LocalDate today(String id) {
        return jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : LocalDate.now(), id);
    }

    public void setToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", today, id);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * A claim's fields: an amount (required; a number with up to two decimals, 0.00 or more), a date
 * (blank for the sheet's today) and a note (may be empty). Publishes them parsed, with the user making the change.
 */
public class ValidateClaim {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,12}(\\.\\d{1,2})?");

    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> claim,
            Out<ChangedBy> changedBy) throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String date = request == null || request.date() == null ? "" : request.date().trim();
        String note = request == null || request.note() == null ? "" : request.note().trim();
        if (amount.isEmpty()) {
            throw new BadRequestException("Enter an amount");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new BadRequestException("An amount is a number, 0.00 or more, with up to two decimals");
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("Enter a date as YYYY-MM-DD");
            }
        }
        if (note.length() > 1000) {
            throw new BadRequestException("A note is at most 1000 characters");
        }
        claim.set(new ClaimInput(new BigDecimal(amount).setScale(2), parsed, note));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildClaim {
    public void build(@Val Person person, @Val ClaimInput input, ClaimRepository repository,
            SheetRepository sheets, Out<Claim> claim) {
        claim.set(repository.insert(person.getSheetId(), person.getId(), input.amount(),
                input.date() != null ? input.date() : sheets.today(person.getSheetId()), input.note()));
    }
}

